sys_variable_value.value:
(function execute(inputs, outputs) {
    var stagingSysId = inputs.staging_sys_id;

    gs.info("[Flow Debug - User Creation] Starting script execution. Input staging_sys_id: " + stagingSysId);

    // 1. Verify input sys_id is passed
    if (!stagingSysId) {
        gs.error("[Flow Debug - User Creation] FAILED: inputs.staging_sys_id is empty or undefined.");
        return;
    }

    var stagingGr = new GlideRecord('x_travel_buddy_app_user_password_registration');

    if (stagingGr.get(stagingSysId)) {
        var username = stagingGr.u_username || stagingGr.u_email;
        gs.info("[Flow Debug - User Creation] Staging record found. Target Username: " + username + " | Email: " + stagingGr.u_email);

        // 2. Check if user already exists in sys_user
        var checkUser = new GlideRecord('sys_user');
        checkUser.addQuery('user_name', username);
        checkUser.query();

        if (checkUser.hasNext()) {
            gs.warn("[Flow Debug - User Creation] SKIPPED: User '" + username + "' already exists in sys_user.");
            return;
        }

        // 3. Create sys_user record
        var userGr = new GlideRecord('sys_user');
        userGr.initialize();
        userGr.first_name = stagingGr.u_first_name;
        userGr.last_name = stagingGr.u_last_name;
        userGr.email = stagingGr.u_email;
        userGr.user_name = username;
        userGr.user_password = stagingGr.u_password;
        userGr.active = true;

        gs.info("[Flow Debug - User Creation] Attempting userGr.insert()...");
        var newUserId = userGr.insert();

        if (newUserId) {
            // 4. Update staging table on success
            stagingGr.u_status = 'completed';
            stagingGr.u_token_used = true;
            stagingGr.update();

            outputs.created_user_sys_id = newUserId;
            outputs.user_email = stagingGr.u_email;

            gs.info("[Flow Debug - User Creation] SUCCESS: Created sys_user record ID: " + newUserId + " and updated staging status to 'completed'.");
        } else {
            gs.error("[Flow Debug - User Creation] FAILED: userGr.insert() returned null. Check mandatory fields or Data Policies on sys_user.");
        }
    } else {
        gs.error("[Flow Debug - User Creation] FAILED: Staging record not found for sys_id: " + stagingSysId);
    }
})(inputs, outputs);

